const data = $json;

let result = data.output;

if (typeof result !== "string") {
  result = JSON.stringify(result);
}

result = result
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(result);
} catch (error) {
  throw new Error("Invalid JSON returned by AI");
}

return {
  json: {
    ...data,
    ...parsed
  }
};

const items = $input.all();

const requiredFields = [
  "Ticket_ID",
  "Customer_ID",
  "Customer_Name",
  "Customer_Email",
  "Issue",
  "Category",
  "Priority",
  "Days_Open",
  "Previous_Escalations"
];

const validItems = [];
const invalidItems = [];

for (const item of items) {

  const data = item.json;

  const missingFields = requiredFields.filter(
    field =>
      data[field] === undefined ||
      data[field] === null ||
      String(data[field]).trim() === ""
  );

  const daysOpen = Number(data.Days_Open);
  const previousEscalations =
    Number(data.Previous_Escalations);

  if (
    missingFields.length === 0 &&
    !isNaN(daysOpen) &&
    !isNaN(previousEscalations)
  ) {

    validItems.push({
      ...data,
      Days_Open: daysOpen,
      Previous_Escalations: previousEscalations
    });

  } else {

    invalidItems.push({
      ticket_id: data.Ticket_ID || "Unknown",
      missing_fields: missingFields
    });

  }
}

return [
  {
    json: {
      data_valid: invalidItems.length === 0,
      total_tickets: items.length,
      valid_tickets: validItems.length,
      invalid_tickets: invalidItems.length,
      invalid_details: invalidItems,
      ticket_data: validItems
    }
  }
];

const data = $json.ticket_data;

const analyzedTickets = [];

for (const ticket of data) {

  const priority =
    String(ticket.Priority).toLowerCase();

  const daysOpen =
    Number(ticket.Days_Open);

  const previousEscalations =
    Number(ticket.Previous_Escalations);

  let escalationScore = 0;

  if (priority === "critical") {
    escalationScore += 4;
  } else if (priority === "high") {
    escalationScore += 3;
  } else if (priority === "medium") {
    escalationScore += 2;
  } else {
    escalationScore += 1;
  }

  if (daysOpen >= 7) {
    escalationScore += 3;
  } else if (daysOpen >= 3) {
    escalationScore += 2;
  }

  if (previousEscalations >= 2) {
    escalationScore += 3;
  } else if (previousEscalations === 1) {
    escalationScore += 1;
  }

  let initialSeverity;

  if (escalationScore >= 7) {
    initialSeverity = "CRITICAL";
  } else if (escalationScore >= 5) {
    initialSeverity = "HIGH";
  } else if (escalationScore >= 3) {
    initialSeverity = "MEDIUM";
  } else {
    initialSeverity = "LOW";
  }

  analyzedTickets.push({
    ...ticket,
    escalation_score: escalationScore,
    initial_severity: initialSeverity
  });
}

return [
  {
    json: {
      analyzed_tickets: analyzedTickets
    }
  }
];

